contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint v, uint w) public payable {
        require(true);

        // First call to SetMinSum before initialization must succeed and set MinSum = v.
        c.SetMinSum(v); if (__ESBMC_reverted()) return;
        uint afterFirst = c.MinSum(); if (__ESBMC_reverted()) return;

        // A second SetMinSum before Initialized() must also succeed and update MinSum to w.
        c.SetMinSum(w); if (__ESBMC_reverted()) return;
        uint afterSecond = c.MinSum(); if (__ESBMC_reverted()) return;

        assert(afterFirst == v && afterSecond == w);
    }

    receive() external payable {}
}

