pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {MONEY_BOX} from "../src/MONEY_BOX.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    MONEY_BOX c;

    function setUp() public {
        c = new MONEY_BOX();
    }

    function _run(uint256 v, uint256 w) internal {
        vm.assume(true);
        try c.SetMinSum(v) {} catch { return; }
        uint256 afterFirst;
        try c.MinSum() returns (uint256 __r) { afterFirst = __r; } catch { return; }
        try c.SetMinSum(w) {} catch { return; }
        uint256 afterSecond;
        try c.MinSum() returns (uint256 __r) { afterSecond = __r; } catch { return; }
        assertTrue(afterFirst == v && afterSecond == w);
    }

    function testFuzz_run(uint256 v, uint256 w) public {
        _run(v, w);
    }

    receive() external payable {}
}
